import * as THREE from 'three';

/**
 * Hull GLB variants generated by scripts/blender (generate_hull.py -> V7 backup, generate_hull_v8c.py -> V8-C).
 * V8-C is the default; load the V7 backup with ?hull=v7; compare them side by side on /hull-compare.html.
 */
export const HULL_VARIANTS = {
  v7: { file: 'blender-hull-V7.glb', label: 'V7 (backup)', blurb: 'The existing hull: smooth-modifier loft, flat materials.' },
  v8c: { file: 'blender-hull-V8C.glb', label: 'V8-C Modern Feeder (default)', blurb: 'Contemporary feeder: weathered paint, raised forecastle, tripod mast + radomes, free-fall lifeboat, fire main.' }
} as const;

export type HullVariant = keyof typeof HULL_VARIANTS;
export const DEFAULT_HULL: HullVariant = 'v8c';

export function isHullVariant(value: string | null | undefined): value is HullVariant {
  return !!value && Object.prototype.hasOwnProperty.call(HULL_VARIANTS, value);
}

/** Hull chosen with the ?hull= query parameter, falling back to the default. */
export function selectedHullVariant(): HullVariant {
  if (typeof window === 'undefined') return DEFAULT_HULL;
  const requested = new URLSearchParams(window.location.search).get('hull')?.toLowerCase();
  return isHullVariant(requested) ? requested : DEFAULT_HULL;
}

export type HullLook = 'glass' | 'solid';

type MaterialLook = { transparent: boolean; opacity: number; depthWrite: boolean; side: THREE.Side; transmission?: number };
const lookOf = (m: THREE.Material): MaterialLook => {
  const look: MaterialLook = { transparent: m.transparent, opacity: m.opacity, depthWrite: m.depthWrite, side: m.side };
  if ('transmission' in m) look.transmission = (m as THREE.MeshPhysicalMaterial).transmission;
  return look;
};
const meshesOf = (root: THREE.Object3D) => {
  const meshes: THREE.Mesh[] = [];
  root.traverse((o) => { if (o instanceof THREE.Mesh) meshes.push(o); });
  return meshes;
};
const materialsOf = (mesh: THREE.Mesh) => (Array.isArray(mesh.material) ? mesh.material : [mesh.material]);

/**
 * Show a loaded hull either in the simulator's translucent 'glass' look (machinery visible inside) or 'solid', as
 * exported from Blender (painted, textured, opaque). The first call records both looks so later calls just switch.
 */
export function setHullLook(root: THREE.Object3D, look: HullLook): void {
  if (!root.userData.hullLooks) {
    for (const mesh of meshesOf(root)) {
      mesh.userData.renderOrders = { solid: mesh.renderOrder };
      for (const m of materialsOf(mesh)) m.userData.looks ??= { solid: lookOf(m) };
    }
    applyAppHullStyle(root);
    for (const mesh of meshesOf(root)) {
      mesh.userData.renderOrders.glass = mesh.renderOrder;
      for (const m of materialsOf(mesh)) m.userData.looks.glass ??= lookOf(m);
    }
    root.userData.hullLooks = true;
  }
  for (const mesh of meshesOf(root)) {
    mesh.renderOrder = mesh.userData.renderOrders[look];
    for (const m of materialsOf(mesh)) {
      Object.assign(m, m.userData.looks[look]);
      m.needsUpdate = true;
    }
  }
}

/**
 * The simulator's "glass ship" look: translucent plating and superstructure so the machinery inside stays visible,
 * solid foundation pads, semi-transparent hardware. Classification is by material / object name keywords, which every
 * hull generator keeps stable (Hull_Topsides, Hull_Under, Waterline, Superstructure, Deck_Marine_Slate, Internal_Deck_Bulkhead, ...).
 */
export function applyAppHullStyle(root: THREE.Object3D): void {
  root.traverse((child) => {
    if (!(child instanceof THREE.Mesh)) return;
    const materials = Array.isArray(child.material) ? child.material : [child.material];
    materials.forEach((mat) => {
      // Disable transmission if present so standard alpha blending works reliably
      if ('transmission' in mat) (mat as THREE.MeshPhysicalMaterial).transmission = 0;
      const matName = mat.name || '';
      const meshName = child.name || '';
      const ghost = (opacity: number, order: number, doubleSide = true) => {
        mat.transparent = true;
        mat.opacity = opacity;
        mat.depthWrite = false;
        if (doubleSide) mat.side = THREE.DoubleSide;
        child.renderOrder = order;
      };

      // 1. Translucent hull plating (underwater, topsides, rudder blade, bossings)
      if (
        matName.includes('Hull_Under') ||
        matName.includes('Hull_Topsides') ||
        matName.includes('Topsides') ||
        (meshName === 'ShipHull' && (matName.includes('RedOxide') || matName.includes('NavyCyan'))) ||
        meshName.includes('Bossing') ||
        meshName.includes('Boss_Fairing') ||
        meshName === 'SemiBalanced_Rudder'
      ) ghost(0.32, 3);
      // 2. Waterline / boot-top band
      else if (matName.includes('Waterline')) ghost(0.40, 3);
      // 3. Superstructure & accommodation house (translucent so interior switchboards/generators are visible)
      else if (matName.includes('Superstructure') || meshName.includes('Accommodation')) ghost(0.32, 3);
      // 4. Equipment foundation pads (solid & clearly legible under machinery)
      else if (matName.includes('Equipment_Foundation_Pad') || meshName.startsWith('Pad_')) {
        mat.transparent = false;
        mat.opacity = 1.0;
        mat.depthWrite = true;
      }
      // 5. Decks and cargo bay pads
      else if (matName.includes('Deck_Marine_Slate') || meshName.includes('CargoBay_Pad') || meshName.includes('House_Deck')) ghost(0.40, 1);
      // 6. Internal deck flats, structure, tanks and watertight bulkheads
      else if (
        matName.includes('Internal_Deck_Bulkhead') ||
        meshName.includes('TankTop') ||
        meshName.includes('Mezzanine') ||
        meshName.includes('Bulkhead')
      ) ghost(0.35, 1);
      // 7. Windows
      else if (matName.includes('Window') || meshName.includes('Window')) ghost(0.35, 3, false);
      // 8. Funnel casing & accents
      else if (matName.includes('Funnel') || meshName.includes('Funnel')) ghost(0.40, 3);
      // 9. Deck hardware, winches, bollards, rails, markings & thruster grates
      else ghost(matName.includes('Rail') ? 0.45 : 0.55, 4, false);
    });
  });
}
